<?php
require __DIR__.'/config/auth.php';requireLogin();require __DIR__.'/config/db.php';require __DIR__.'/config/layout.php';
$q=trim($_GET['q']??'');$rows=[];$sectores=sectoresVisibles($pdo);$ids=array_map(fn($s)=>(int)$s['id'],$sectores);$slugById=[];foreach($sectores as $sv)$slugById[(int)$sv['id']]=$sv['slug'];
if($q!==''&&$ids){$ph=implode(',',array_fill(0,count($ids),'?'));$sql="SELECT d.*,s.nombre sector,c.nombre carpeta FROM documentos d JOIN sectores s ON s.id=d.sector_id LEFT JOIN carpetas c ON c.id=d.carpeta_id WHERE d.activo=1 AND d.sector_id IN ($ph) AND (d.titulo LIKE ? OR d.descripcion LIKE ? OR d.nombre_original LIKE ?) ORDER BY d.fecha_actualizacion DESC,d.titulo LIMIT 200";$like='%'.$q.'%';$st=$pdo->prepare($sql);$st->execute([...$ids,$like,$like,$like]);$rows=$st->fetchAll();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Buscar | NASER</title><link rel="stylesheet" href="<?=app_url('/style.css')?>"></head><body><div class="app"><?php sidebar($pdo,'buscar');?><main class="content"><header class="section-top"><div><p class="eyebrow">DOCUMENTACIÓN</p><h1>Buscar documentos</h1><p>Buscá en todos los sectores habilitados.</p></div></header><form class="search-bar" method="get"><input name="q" value="<?=h($q)?>" placeholder="Nombre, palabra clave o archivo..." autofocus><button class="btn primary">Buscar</button></form><?php if($q!==''):?><div class="section-head"><div><h2>Resultados</h2><p><?=count($rows)?> coincidencia(s)</p></div></div><section class="document-grid"><?php if(!$rows):?><div class="empty">No se encontraron documentos.</div><?php endif;?><?php foreach($rows as $d):?><article class="document-card"><div class="doc-meta"><span class="type-badge"><?=h($d['sector'])?></span><span class="status-pill <?=h($d['estado'])?>"><?=h($d['estado'])?></span></div><h3><?=h($d['titulo'])?></h3><p><?=h($d['descripcion']?:($d['carpeta']??'Sin carpeta'))?></p><div class="doc-actions"><a class="btn secondary" href="<?=app_url('/php/sector.php?sector='.urlencode($slugById[(int)$d['sector_id']] ?? 'sgi').'&carpeta='.(int)($d['carpeta_id']??0))?>">Ubicación</a><?php if($d['archivo']):?><a class="btn primary" target="_blank" href="<?=app_url('/uploads/'.rawurlencode($d['archivo']))?>">Abrir</a><?php endif;?></div></article><?php endforeach;?></section><?php endif;?></main></div></body></html>
